mapper.select:
SELECT 
FROM cut_cutover_checklist_item
WHERE tenant_id = #{query.tenantId}
  AND checklist_id = #{query.checklistId}
  AND deleted = b'0'
ORDER BY sort_order, stable_item_key, id

mapper.update:
UPDATE cut_cutover_checklist_item
SET applicable_flag = b'0',
    updater = #{query.actorId},
    version = version + 1,
    update_time = NOW(3)
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.itemId}
  AND source_code = 'CUSTOM'
  AND custom_creator_user_id = #{query.actorId}
  AND applicable_flag = b'1'
  AND version = #{query.expectedVersion}
  AND deleted = b'0'
